const e="data:image/svg+xml,%3csvg%20xmlns='http://www.w3.org/2000/svg'%20width='20'%20height='20'%20viewBox='0%200%2020%2020'%20fill='none'%3e%3c!--%20刷新图标（会议页「历史记录」右侧按钮）：缺口圆环%20+%20单向箭头，色%20%236b6a75。%201)%20圆弧%20——%20圆心%20(10,10)、半径%207.1、笔画%201.8；从%2012:00%20(10,%202.9)%20逆时针绕%20270°%20到%203:00%20(17.1,%2010)，缺口正好落在右上象限。端点按%20SVG%20圆弧语义%20=%20butt%20端帽，%2012:00%20那条端帽就是径向切面%20x=10、y%202.0→3.8%20的竖直线段。%202)%20箭头%20——%20实心三角，底边与上面那条切面**同一条竖直轴**，并故意往弧线里压进%200.8（底边取%20x=9.2），吃掉浮点抗锯齿产生的发丝缝；尖朝右指向缺口，即顺时针方向。%20★几何在这里一次画准，端上只当普通图片渲染（与「新的伙伴」同一套%20svg%20通道）。%20之前用%20border%20+%20transform%20手拼，箭头与弧线只是「理论相切」，各端对%20border-radius%20缺口角度和旋转舍入的处理不同，真机渲染接不上，故弃用。%20--%3e%3cpath%20d='M10%202.9A7.1%207.1%200%201%200%2017.1%2010'%20stroke='%236b6a75'%20stroke-width='1.8'%20stroke-linecap='butt'%20fill='none'%20/%3e%3c!--%20三角同时给%20stroke：既把尖角磨圆一点，也兜住「不支持纯填充路径」的渲染器%20（最坏情况退回成同色的%20V%20形线稿，仍然接在弧线端帽上）%20--%3e%3cpath%20d='M9.2%200.7L14.8%202.9L9.2%205.1Z'%20fill='%236b6a75'%20stroke='%236b6a75'%20stroke-width='0.6'%20stroke-linejoin='round'%20/%3e%3c/svg%3e";export{e as i};
